schema: reverse-kit-record/1
game: wol
status: draft
system:
  id: '03'
  slug: juice
  title: 'Сочность: частицы, цифры, хитстоп'
  buckets:
  - juice
goal: 'Показать обратную связь на экране без вмешательства в правила боя: частицы пыли, обломков, листвы и огня, трещины пола, ноты и эмоции, земляные столб и колесо. Фиксирует числа выпусков, таймеры и общий контракт слоя частиц, чтобы клон давал тот же отклик.'
rules:
- id: J1.air-step-dedupe
  title: Подавление повторных облачков воздуха от шагов в воздухе
  behavior: Облачко воздуха от шага в воздухе ставится в точке, сдвинутой на 0.5 м вправо и 0.5 м вниз от заданной; вне игровых ярусов к точке добавляется положение активной комнаты. Если в этой же точке такое облачко уже ставилось менее 0.75 с назад — новое не создаётся, иначе запоминается время и частицы испускаются по общему контракту слоя частиц. Ключ сравнения — точное совпадение координаты.
  numbers:
    dedupe_window:
      value: 0.75
      unit: с
    offset_x:
      value: 0.5
      unit: м
    offset_y:
      value: -0.5
      unit: м
  conditions:
  - вне ярусных сцен добавляется смещение активной комнаты
  source_refs:
  - AirWalkEmitter.cs:12-52
  confidence: high
  tags:
  - particles
- id: J2.anim-effect
  title: 'Анимационный эффект: включение, одноразовый проигрыш, самовыключение'
  behavior: Объект-эффект на старте выключен, пока его не запустили. Запуск включает объект, ставит позицию и равномерный масштаб, поворот (по умолчанию — исходный), выбирает клип (по умолчанию — заданный) и стартовую долю клипа (фиксированную или случайную в диапазоне) и скорость. Фактический запуск клипа откладывается на конец кадра; в первом кадре после запуска проверка окончания пропускается. Когда клип доигран, объект выключается. Есть флаг «не проверять окончание» для эффектов, которые выключает кто-то другой.
  numbers:
    default_speed:
      value: 1
    default_scale:
      value: 1
  conditions:
  - проверка окончания пропускается в кадре запуска и если флаг «не проверять» включён
  source_refs:
  - AnimEffect.cs:21-100
  confidence: high
  tags:
  - anim
- id: J3.aux-effect-record
  title: Запись вспомогательного эффекта при основном
  behavior: 'Основной эффект частиц может нести список вспомогательных записей. Каждая запись задаёт: имя эффекта в пуле, число частиц (по умолчанию 10), переопределения параметров, угол, задержку, поправку порядка отрисовки, смещение от точки основного эффекта и объект, за которым следовать. Смещение прибавляется к позиции основного залпа; если у основного позиция не задана — вспомогательному она тоже не задаётся. Листовой вариант записи дополнительно хранит цвет листвы (по умолчанию зелёный).'
  numbers:
    default_particle_count:
      value: 10
      unit: частиц
  source_refs:
  - AuxParticleEffect.cs:5-45
  - LeafAuxParticleEffect.cs:5-15
  - ParticleEffect.cs:134-142
  confidence: high
  tags:
  - particles
using System;
using System.Collections.Generic;
using System.IO;
using System.Text;
using System.Threading;

namespace Common.gamestate;

public class GameLog
{
	private Queue<string> logs = new Queue<string>();

	private bool isInit;

	private string path;

	private string filePath;

	private Thread thread;

	private bool isRunning;

	private int writeFailures;

	private static GameLog gameLog = new GameLog();

	public void InitInternal(string path)
	{
		try
		{
			DateTime now = DateTime.Now;
			filePath = Path.Combine(path, "log_" + now.ToString("yyyy_MM_dd_") + ((int)now.TimeOfDay.TotalSeconds).ToString("00000") + ".log");
			Directory.CreateDirectory(path);
			this.path = path;
			string[] files = Directory.GetFiles(path, "log_*.log", SearchOption.TopDirectoryOnly);
			if (files.Length > 4)
			{
				Array.Sort(files);
				for (int num = files.Length; num > 4; num--)
				{
					File.Delete(files[files.Length - num]);
				}
			}
			File.Create(filePath);
			isInit = true;
			thread = new Thread(LogProc);
			StartLogging();
		}
		catch (Exception ex)
		{
			Console.WriteLine("Log init failure: " + ex.Message, false);
		}
		isInit = true;
		isRunning = true;
	}

	public void StartLogging()
	{
		if (isInit && !isRunning)
		{
			isRunning = true;
			thread.Start();
		}
	}

	public void StopLogging()
	{
		isRunning = false;
	}

	public void LogProc()
	{
		while (isRunning)
		{
			if (logs.Count > 0)
			{
				WriteLogsToFile();
			}
			Thread.Sleep(1000);
		}
	}

	public void WriteLogsToFile()
	{
		StringBuilder stringBuilder = new StringBuilder();
		lock (logs)
		{
			while (logs.Count > 0)
			{
				stringBuilder.AppendLine(logs.Dequeue());
			}
		}
		try
		{
			File.AppendAllText(filePath, stringBuilder.ToString());
			writeFailures = 0;
		}
		catch (Exception ex)
		{
			Console.WriteLine("Log write failure: " + ex.Message, false);
			writeFailures++;
			if (writeFailures >= 3)
			{
				Console.WriteLine("Too many log write failures. Stopping logging.", false);
				isRunning = false;
			}
		}
	}

	public void WriteLogInternal(string log)
	{
		lock (logs)
		{
			logs.Enqueue("[" + DateTime.Now.ToLongTimeString() + "] " + log);
		}
	}

	public static void Init(string path)
	{
		gameLog.InitInternal(path);
	}

	public static void Stop()
	{
		gameLog.StopLogging();
	}

	public static void WriteLog(string log)
	{
		if (gameLog.isInit && gameLog.isRunning)
		{
			gameLog.WriteLogInternal(log);
		}
	}

	public static List<string> GetAllLogsDump()
	{
		List<string> list = new List<string>(1000);
		if (gameLog.isInit)
		{
			string[] files = Directory.GetFiles(gameLog.path, "*.log", SearchOption.TopDirectoryOnly);
			Array.Sort(files);
			Array.Reverse(files);
			for (int i = 0; i < files.Length; i++)
			{
				try
				{
					list.Add("");
					list.Add("=");
