		{
			float num2 = 1f - p.frame;
			Textures.tex[ParticleManager.spritesTexIdx].Draw(ScrollManager.GetScreenLoc(loc, 0), p.flags, new Vector2(num2, num2) * ScrollManager.cannedDepth[0] * 0.4f, p.size, 1f, 0.7f, 0.6f, p.frame);
