		if (p.aux > -1 && ParticleManager.particleList[5].particle[p.aux].type == 100)
		{
			loc = (p.loc + ParticleManager.particleList[5].particle[p.aux].loc) / 2f;
			p.rotation = Trig.GetAngle(p.loc, ParticleManager.particleList[5].particle[p.aux].loc);
			num = Trig.GetDist(p.loc, ParticleManager.particleList[5].particle[p.aux].loc) / 40f;
		}
		float num3 = 0.3f + (1f - p.frame) * 2f;
		float num4 = p.frame * 2f;
		if (num4 > 0.5f)
