			}
		}
		if (p.aux % 8 != 0 && num3 > 0.5f)
		{
			num4 -= (num3 - 0.5f) * 2f;
		}
		if (num4 > 0f)
		{
			if (num3 > 0.65f)
			{
				num3 = 0.65f + (num3 - 0.65f) * 0.1f;
			}
			Textures.tex[ParticleManager.spritesTexIdx].Draw(ScrollManager.GetScreenLoc(loc, 0), p.flags, new Vector2(num3, num3) * ScrollManager.cannedDepth[0] * 0.8f, p.size, 1f, 0.7f, 0.6f, num4 * 0.5f);
		}
		base.Draw(p, brite);
	}
